INSERT INTO faqs (question, answer_md, answer_html, sort_order, is_published)
SELECT 'How do you price work?', 'Onboarding is a flat fixed fee and produces a written process map and a scoped recommendation — you own it whether or not you continue. Build work is then quoted at a fixed price per phase, agreed after the prototype has settled the scope, so the number you approve is the number you pay. Ongoing support is a modest monthly retainer, cancellable. We do not bill open-ended hourly for defined work.', '<p>Onboarding is a flat fixed fee and produces a written process map and a scoped recommendation — you own it whether or not you continue. Build work is then quoted at a fixed price per phase, agreed after the prototype has settled the scope, so the number you approve is the number you pay. Ongoing support is a modest monthly retainer, cancellable. We do not bill open-ended hourly for defined work.</p>', 1, true
WHERE NOT EXISTS (SELECT 1 FROM faqs WHERE question = 'How do you price work?');
INSERT INTO faqs (question, answer_md, answer_html, sort_order, is_published)
SELECT 'How long does a first system take?', 'Most systems are in your team''s hands within two to four weeks: a working prototype you can log into in the first week or two, then a running system one or two cycles after that. Small automations often ship in days. Larger builds spanning several external systems run longer, and the case studies on this site name their real timelines. Either way there are no dark months — you see working software every week.', '<p>Most systems are in your team&rsquo;s hands within two to four weeks: a working prototype you can log into in the first week or two, then a running system one or two cycles after that. Small automations often ship in days. Larger builds spanning several external systems run longer, and the case studies on this site name their real timelines. Either way there are no dark months — you see working software every week.</p>', 2, true
WHERE NOT EXISTS (SELECT 1 FROM faqs WHERE question = 'How long does a first system take?');
INSERT INTO faqs (question, answer_md, answer_html, sort_order, is_published)
SELECT 'Who owns the code and the data?', 'You do, both, outright. You get the repository, the installer and the documentation, and there is no licence, no platform fee and no clause that makes leaving expensive. Everything ships as a standard Docker stack with plain-SQL migrations, so another developer can pick it up. Nothing we build requires us to stay — that is deliberate, and it keeps us honest.', '<p>You do, both, outright. You get the repository, the installer and the documentation, and there is no licence, no platform fee and no clause that makes leaving expensive. Everything ships as a standard Docker stack with plain-SQL migrations, so another developer can pick it up. Nothing we build requires us to stay — that is deliberate, and it keeps us honest.</p>', 3, true
WHERE NOT EXISTS (SELECT 1 FROM faqs WHERE question = 'Who owns the code and the data?');
INSERT INTO faqs (question, answer_md, answer_html, sort_order, is_published)
SELECT 'Will this work with the systems we already have?', 'That is most of what we do. We have integrated SQL Server back offices, Shopify storefronts, carrier and shipping platforms, payment processors and accounting systems — often several at once, in both directions. Age is rarely the obstacle; if a system has an API or a database we can read, we can usually work with it. We check exactly this during discovery, before you commit to a build.', '<p>That is most of what we do. We have integrated SQL Server back offices, Shopify storefronts, carrier and shipping platforms, payment processors and accounting systems — often several at once, in both directions. Age is rarely the obstacle; if a system has an API or a database we can read, we can usually work with it. We check exactly this during discovery, before you commit to a build.</p>', 4, true
WHERE NOT EXISTS (SELECT 1 FROM faqs WHERE question = 'Will this work with the systems we already have?');
INSERT INTO faqs (question, answer_md, answer_html, sort_order, is_published)
SELECT 'We already have a developer. Does that change anything?', 'Usually for the better. We often build the piece that needs specialist integration work and hand it over, or we work alongside an internal developer who knows your domain better than we ever will. We write for the next person by default: standard stacks, plain SQL, documented deployment. If your developer would rather own it entirely, that is a good outcome, not a lost sale.', '<p>Usually for the better. We often build the piece that needs specialist integration work and hand it over, or we work alongside an internal developer who knows your domain better than we ever will. We write for the next person by default: standard stacks, plain SQL, documented deployment. If your developer would rather own it entirely, that is a good outcome, not a lost sale.</p>', 5, true
WHERE NOT EXISTS (SELECT 1 FROM faqs WHERE question = 'We already have a developer. Does that change anything?');
INSERT INTO faqs (question, answer_md, answer_html, sort_order, is_published)
SELECT 'What happens after launch?', 'The people who built it maintain it. Systems that touch other companies'' APIs need someone watching, because platform versions change whether or not you asked. A support retainer covers monitoring, fixes, upstream changes and small improvements, with an agreed response time and a monthly note on what changed. You can also take the whole thing in-house — the installer and docs exist for exactly that.', '<p>The people who built it maintain it. Systems that touch other companies&rsquo; APIs need someone watching, because platform versions change whether or not you asked. A support retainer covers monitoring, fixes, upstream changes and small improvements, with an agreed response time and a monthly note on what changed. You can also take the whole thing in-house — the installer and docs exist for exactly that.</p>', 6, true
WHERE NOT EXISTS (SELECT 1 FROM faqs WHERE question = 'What happens after launch?');
INSERT INTO faqs (question, answer_md, answer_html, sort_order, is_published)
SELECT 'How do you handle our data?', 'Systems run on your infrastructure whenever you want them to, and the data stays in your database. Secrets live in environment files, never in code, and API tokens are masked in every interface. Access is role-based, and anything touching stock or money is written with a user and a timestamp. For work involving live data we sign an NDA before discovery, and we sanitise anything used for demonstration.', '<p>Systems run on your infrastructure whenever you want them to, and the data stays in your database. Secrets live in environment files, never in code, and API tokens are masked in every interface. Access is role-based, and anything touching stock or money is written with a user and a timestamp. For work involving live data we sign an NDA before discovery, and we sanitise anything used for demonstration.</p>', 7, true
WHERE NOT EXISTS (SELECT 1 FROM faqs WHERE question = 'How do you handle our data?');
